# construct demo1 data and test proposed horizontal behavior
D1=[[0]*17 for _ in range(11)]
D1[0][7]=2
for r,holes in [(2,[5,9]),(4,[2,12]),(7,[5])]:
 for c in range(17): D1[r][c]=0 if c in holes else 8

def horiz(grid):
 g=[row[:] for row in grid]; H=len(g); W=len(g[0])
 seeds=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
 r0,c0=seeds[0]
 bars=[r for r,row in enumerate(g) if 8 in row]
 current={c0}
 for k,r in enumerate(bars):
  holes=[c for c,v in enumerate(g[r]) if v==0]
  if not holes: continue
  selected=set()
  for x in current:
   ds=[abs(c-x) for c in holes]; m=min(ds)
   selected.update(c for c,d in zip(holes,ds) if d==m)
  # ensure selection
  for c in selected:g[r][c]=2
  if r>0:
   if len(selected)==1: a,b=0,W-1
   else:a,b=min(selected),max(selected)
   for c in range(a,b+1):
    if g[r-1][c]==0:g[r-1][c]=2
  if k==len(bars)-1:
   for rr in range(r+1,H):
    for c in selected:
     if g[rr][c]==0:g[rr][c]=2
  elif r+1<H:
   for c in selected:
    if g[r+1][c]==0:g[r+1][c]=2
  current=selected
 return g
O1=horiz(D1)
print('\n'.join(' '.join(map(str,row)) for row in O1))

