def seed_nearest_path(grid):
 g=[row[:] for row in grid]; bars=[r for r,row in enumerate(grid) if 8 in row]; H=len(g); W=len(g[0]); seed=next(c for row in grid for c,v in enumerate(row) if v==2); cur=seed
 selected=[]
 for r in bars:
  holes=[c for c,v in enumerate(grid[r]) if v==0]
  ds=[abs(c-seed) for c in holes]; d=min(ds); s={c for c,v in zip(holes,ds) if v==d}; selected.append(s)
  for c in s:g[r][c]=2
  if r>0:
   a,b=min({cur}|s),max({cur}|s)
   for c in range(a,b+1):
    if g[r-1][c]==0:g[r-1][c]=2
  if r+1<H:
   for c in s:
    if g[r+1][c]==0:g[r+1][c]=2
  cur=next(iter(s))
 for r in range(bars[-1]+1,H):
  for c in selected[-1]:
   if g[r][c]==0:g[r][c]=2
 return g
